content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --secondary-color: #f3f4f6;
  --secondary-hover: #e5e7eb;
  --text-color: #1f2937;
  --text-light: #6b7280;
  --bg-color: #f9fafb;
  --card-bg: #ffffff;
  --border-color: #e5e7eb;
  --success-color: #10b981;
  --danger-color: #ef4444;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

@media (prefers-color-scheme: dark) {
  :root {
    --primary-color: #6366f1;
    --primary-hover: #4f46e5;
    --secondary-color: #374151;
    --secondary-hover: #4b5563;
    --text-color: #f3f4f6;
    --text-light: #9ca3af;
    --bg-color: #111827;
    --card-bg: #1f2937;
    --border-color: #374151;
    --success-color: #10b981;
    --danger-color: #ef4444;
    --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.3), 0 2px 4px -1px rgba(0, 0, 0, 0.18);
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  line-height: 1.5;
  padding: 20px;
}

.app-container {
  max-width: 900px;
  margin: 0 auto;
  padding: 20px;
}

.header {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 24px;
  background: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

@media (min-width: 640px) {
  .header {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
}

.title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary-color);
}

.stats {
  font-size: 0.95rem;
  color: var(--text-light);
  font-weight: 500;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 24px;
  align-items: center;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 18px;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
  background-color: var(--card-bg);
  color: var(--text-color);
  cursor: pointer;
  transition: all 0.2s ease;
  user-select: none;
}

.btn:hover {
  background-color: var(--secondary-color);
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
  border-color: var(--primary-color);
}

.btn-primary:hover {
  background-color: var(--primary-hover);
  border-color: var(--primary-hover);
}

.btn-secondary {
  background-color: var(--secondary-color);
  color: var(--text-color);
}

.btn-secondary:hover {
  background-color: var(--secondary-hover);
}

.select, .input {
  padding: 10px 14px;
  font-size: 0.95rem;
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
  background-color: var(--card-bg);
  color: var(--text-color);
  outline: none;
  transition: border-color 0.2s;
}

.select:focus, .input:focus {
  border-color: var(--primary-color);
}

.card-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
}

@media (min-width: 640px) {
  .card-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.card-container {
  perspective: 1000px;
  width: 100%;
  height: 280px;
}

.flashcard {
  width: 100%;
  height: 100%;
  cursor: pointer;
  background: transparent;
  border: none;
  padding: 0;
}

.flashcard-inner {
  position: relative;
  width: 100%;
  height: 100%;
  text-align: center;
  transition: transform 0.6s;
  transform-style: preserve-3d;
  -webkit-transform-style: preserve-3d;
  box-shadow: var(--shadow);
  border-radius: var(--radius);
}

.flashcard.flipped .flashcard-inner {
  transform: rotateY(180deg);
}

.flashcard-front, .flashcard-back {
  position: absolute;
  width: 100%;
  height: 100%;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 24px;
  background-color: var(--card-bg);
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
}

.flashcard-back {
  transform: rotateY(180deg);
  background-color: #faf5ff;
  border-color: #e9d5ff;
}

@media (prefers-color-scheme: dark) {
  .flashcard-back {
    background-color: #2e1065;
    border-color: #581c87;
  }
}

.badge {
  display: inline-block;
  padding: 4px 10px;
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: 9999px;
  background-color: #e0e7ff;
  color: var(--primary-color);
  align-self: flex-start;
}

@media (prefers-color-scheme: dark) {
  .badge {
    background-color: #312e81;
    color: #818cf8;
  }
}

.word-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.empty-msg {
  text-align: center;
  padding: 40px;
  color: var(--text-light);
  background: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.add-form {
  background: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 16px;
  max-width: 600px;
  margin: 0 auto;
}

export type ViewMode = 'study' | 'list' | 'add';

export type Category = '基本' | '日常会話' | 'ビジネス' | '学術' | 'その他' | string;

export interface WordCard {
  id: string;
  english: string;
  japanese: string;
  example: string;
  category: Category;
  remembered: boolean;
}

export interface FlashcardProps {
  card: WordCard;
  onToggleRemembered: (id: string) => void;
}

export interface WordListProps {
  cards: WordCard[];
  onToggleRemembered: (id: string) => void;
  onDelete: (id: string) => void;
}

export interface AddWordProps {
  onAdd: (card: Omit<WordCard, 'id' | 'remembered'>) => void;
}

import { useState } from 'react';
import { FlashcardProps } from '../types';

export default function Flashcard({ card, onToggleRemembered }: FlashcardProps) {
  const [isFlipped, setIsFlipped] = useState(false);

  const handleCardClick = () => {
    setIsFlipped(!isFlipped);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      setIsFlipped(!isFlipped);
    }
  };

  const handleCheckboxClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    onToggleRemembered(card.id);
  };

  return (
    <div className="card-container">
      <div 
        className={`flashcard ${isFlipped ? 'flipped' : ''}`}
        onClick={handleCardClick}
        onKeyDown={handleKeyDown}
        role="button"
        tabIndex={0}
        aria-pressed={isFlipped}
        aria-label={`${card.english}のフラッシュカード。クリックまたはキーボードで裏返します。`}
      >
        <div className="flashcard-inner">
          <div className="flashcard-front">
            <span className="badge">{card.category}</span>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
              <h2 style={{ fontSize: '1.8rem', fontWeight: 700, color: 'var(--primary-color)' }}>
                {card.english}
              </h2>
              <p style={{ fontSize: '0.95rem', color: 'var(--text-light)', fontStyle: 'italic' }}>
                "{card.example}"
              </p>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%' }}>
              <span style={{ fontSize: '0.85rem', color: 'var(--text-light)' }}>クリックして裏返す</span>
              <button 
                type="button" 
                className="btn btn-secondary" 
                onClick={handleCheckboxClick}
                style={{ padding: '6px 12px', fontSize: '0.85rem' }}
              >
                {card.remembered ? '✅ 覚え済み' : '☐ 未完了'}
              </button>
            </div>
          </div>
          <div className="flashcard-back">
            <span className="badge">日本語訳</span>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
              <h3 style={{ fontSize: '1.5rem', fontWeight: 700, color: 'var(--text-color)' }}>
                {card.japanese}
              </h3>
              <p style={{ fontSize: '0.9rem', color: 'var(--text-light)' }}>
                例文: {card.example}
              </p>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%' }}>
              <span style={{ fontSize: '0.85rem', color: 'var(--text-light)' }}>クリックして戻す</span>
              <button 
                type="button" 
                className="btn btn-secondary" 
                onClick={handleCheckboxClick}
                style={{ padding: '6px 12px', fontSize: '0.85rem' }}
              >
                {card.remembered ? '✅ 覚え済み' : '☐ 未完了'}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { WordListProps } from '../types';

export default function WordList({ cards = [], onToggleRemembered, onDelete }: WordListProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const ITEMS_PER_PAGE = 10;

  const filteredCards = cards.filter((card) => {
    const term = searchTerm.toLowerCase();
    return (
      card.english.toLowerCase().includes(term) ||
      card.japanese.toLowerCase().includes(term) ||
      card.example.toLowerCase().includes(term) ||
      card.category.toLowerCase().includes(term)
    );
  });

  const totalPages = Math.ceil(filteredCards.length / ITEMS_PER_PAGE) || 1;
  const paginatedCards = filteredCards.slice(
    (currentPage - 1) * ITEMS_PER_PAGE,
    currentPage * ITEMS_PER_PAGE
  );

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
    setCurrentPage(1);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
      <div style={{ display: 'flex', gap: '12px', alignItems: 'center' }}>
        <input
          type="text"
          className="input"
          placeholder="単語や意味で検索..."
          value={searchTerm}
          onChange={handleSearchChange}
          style={{ width: '100%', maxWidth: '300px' }}
        />
      </div>

      {filteredCards.length === 0 ? (
        <div className="empty-msg">条件に一致する単語がありません。</div>
      ) : (
        <>
          <div className="word-list">
            {paginatedCards.map((card) => (
              <div 
                key={card.id} 
                style={{ 
                  display: 'flex', 
                  justifyContent: 'space-between', 
                  alignItems: 'center', 
                  background: 'var(--card-bg)', 
                  padding: '16px 20px', 
                  borderRadius: 'var(--radius)', 
                  boxShadow: 'var(--shadow)',
                  border: '1px solid var(--border-color)',
                  flexWrap: 'wrap',
                  gap: '12px'
                }}
              >
                <div style={{ display: 'flex', flexDirection: 'column', gap: '4px', flex: 1, minWidth: '200px' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                    <span style={{ fontWeight: 700, fontSize: '1.1rem' }}>{card.english}</span>
                    <span style={{ fontSize: '1rem', color: 'var(--text-light)' }}>- {card.japanese}</span>
                    <span className="badge">{card.category}</span>
                  </div>
                  <span style={{ fontSize: '0.85rem', color: 'var(--text-light)' }}>例文: {card.example}</span>
                </div>
                <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                  <button 
                    type="button" 
                    className="btn btn-secondary"
                    onClick={() => onToggleRemembered(card.id)}
                    style={{ padding: '6px 12px', fontSize: '0.85rem' }}
                  >
                    {card.remembered ? '✅ 覚え済み' : '☐ 未完了'}
                  </button>
                  <button 
                    type="button" 
                    className="btn"
                    onClick={() => onDelete(card.id)}
                    style={{ padding: '6px 12px', fontSize: '0.85rem', color: 'var(--danger-color)', borderColor: 'var(--danger-color)' }}
                  >
                    削除
                  </button>
                </div>
              </div>
            ))}
          </div>

          {totalPages > 1 && (
            <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '12px', marginTop: '12px' }}>
              <button
                type="button"
                className="btn btn-secondary"
                onClick={() => setCurrentPage((p) => Math.max(p - 1, 1))}
                disabled={currentPage === 1}
                style={{ padding: '6px 14px', fontSize: '0.85rem', opacity: currentPage === 1 ? 0.5 : 1 }}
              >
                前へ
              </button>
              <span style={{ fontSize: '0.9rem', color: 'var(--text-light)' }}>
                {currentPage} / {totalPages} ページ
              </span>
              <button
                type="button"
                className="btn btn-secondary"
                onClick={() => setCurrentPage((p) => Math.min(p + 1, totalPages))}
                disabled={currentPage === totalPages}
                style={{ padding: '6px 14px', fontSize: '0.85rem', opacity: currentPage === totalPages ? 0.5 : 1 }}
              >
                次へ
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
}

import { useState } from 'react';
import { AddWordProps } from '../types';

export default function AddWord({ onAdd }: AddWordProps) {
  const [english, setEnglish] = useState('');
  const [japanese, setJapanese] = useState('');
  const [example, setExample] = useState('');
  const [category, setCategory] = useState('基本');
  const [error, setError] = useState('');
  const [successMessage, setSuccessMessage] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccessMessage('');

    if (!english.trim() || !japanese.trim()) {
      setError('英単語と日本語訳は必須です。');
      return;
    }

    onAdd({
      english: english.trim(),
      japanese: japanese.trim(),
      example: example.trim() || `${english.trim()} example.`,
      category: category.trim() || 'その他',
    });

    setSuccessMessage('単語を追加しました！');
    setEnglish('');
    setJapanese('');
    setExample('');
  };

  return (
    <form className="add-form" onSubmit={handleSubmit}>
      <h3 style={{ fontSize: '1.2rem', fontWeight: 700, color: 'var(--primary-color)' }}>新しい単語を追加</h3>

      {error && (
        <div style={{ padding: '10px', background: '#fee2e2', color: '#b91c1c', borderRadius: 'var(--radius)', fontSize: '0.9rem' }}>
          {error}
        </div>
      )}

      {successMessage && (
        <div style={{ padding: '10px', background: '#d1fae5', color: '#047857', borderRadius: 'var(--radius)', fontSize: '0.9rem' }}>
          {successMessage}
        </div>
      )}

      <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
        <label style={{ fontSize: '0.9rem', fontWeight: 600 }}>英単語</label>
        <input 
          type="text" 
          className="input" 
          placeholder="例: apple" 
          value={english}
          onChange={(e) => setEnglish(e.target.value)}
        />
      </div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
        <label style={{ fontSize: '0.9rem', fontWeight: 600 }}>日本語訳</label>
        <input 
          type="text" 
          className="input" 
          placeholder="例: りんご" 
          value={japanese}
          onChange={(e) => setJapanese(e.target.value)}
        />
      </div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
        <label style={{ fontSize: '0.9rem', fontWeight: 600 }}>例文</label>
        <input 
          type="text" 
          className="input" 
          placeholder="例: I eat an apple every day." 
          value={example}
          onChange={(e) => setExample(e.target.value)}
        />
      </div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
        <label style={{ fontSize: '0.9rem', fontWeight: 600 }}>カテゴリ</label>
        <select 
          className="select" 
          value={category}
          onChange={(e) => setCategory(e.target.value)}
        >
          <option value="基本">基本</option>
          <option value="日常会話">日常会話</option>
          <option value="ビジネス">ビジネス</option>
          <option value="学術">学術</option>
          <option value="その他">その他</option>
        </select>
      </div>
      <button type="submit" className="btn btn-primary" style={{ marginTop: '8px' }}>
        追加する
      </button>
    </form>
  );
}

import { useState, useEffect } from 'react';
import './index.css';
import { WordCard } from './types';
import Flashcard from './components/Flashcard';
import WordList from './components/WordList';
import AddWord from './components/AddWord';

const INITIAL_CARDS: WordCard[] = [
  { id: '1', english: 'Apple', japanese: 'りんご', example: 'I eat an apple every day.', category: '基本', remembered: true },
  { id: '2', english: 'Book', japanese: '本', example: 'She is reading an interesting book.', category: '基本', remembered: false },
  { id: '3', english: 'Computer', japanese: 'コンピューター', example: 'He works on his computer.', category: 'ビジネス', remembered: false },
  { id: '4', english: 'Coffee', japanese: 'コーヒー', example: 'I need a cup of coffee in the morning.', category: '日常会話', remembered: true },
  { id: '5', english: 'Journey', japanese: '旅、旅行', example: 'Life is a long journey.', category: '日常会話', remembered: false },
  { id: '6', english: 'Success', japanese: '成功', example: 'Hard work brings success.', category: 'ビジネス', remembered: false },
  { id: '7', english: 'Universe', japanese: '宇宙', example: 'The universe is expanding.', category: '学術', remembered: false },
  { id: '8', english: 'Friend', japanese: '友達', example: 'He is my best friend.', category: '日常会話', remembered: true },
  { id: '9', english: 'Challenge', japanese: '挑戦', example: 'Accept the challenge.', category: 'ビジネス', remembered: false },
  { id: '10', english: 'Smile', japanese: '笑顔', example: 'Her smile brightened the room.', category: '日常会話', remembered: false },
];

const STORAGE_KEY = 'flashcard_app_cards_v1';

export default function App() {
  const [cards, setCards] = useState<WordCard[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        return JSON.parse(saved);
      }
    } catch (e) {
      console.error('Failed to load cards from localStorage', e);
    }
    return INITIAL_CARDS;
  });

  const [viewMode, setViewMode] = useState<'study' | 'list' | 'add'>('study');
  const [selectedCategory, setSelectedCategory] = useState<string>('すべて');

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(cards));
    } catch (e) {
      console.error('Failed to save cards to localStorage', e);
    }
  }, [cards]);

  const handleToggleRemembered = (id: string) => {
    setCards((prev) =>
      prev.map((card) => (card.id === id ? { ...card, remembered: !card.remembered } : card))
    );
  };

  const handleDeleteCard = (id: string) => {
    setCards((prev) => prev.filter((card) => card.id !== id));
  };

  const handleAddCard = (newCardData: Omit<WordCard, 'id' | 'remembered'>) => {
    const newCard: WordCard = {
      ...newCardData,
      id: Date.now().toString(),
      remembered: false,
    };
    setCards((prev) => [newCard, ...prev]);
    setViewMode('study');
  };

  const categories = ['すべて', ...Array.from(new Set(cards.map((c) => c.category)))];

  const filteredCards = cards.filter((card) => {
    if (selectedCategory === 'すべて') return true;
    return card.category === selectedCategory;
  });

  const rememberedCount = cards.filter((c) => c.remembered).length;
  const totalCount = cards.length;

  return (
    <div className="app-container">
      <header className="header">
        <div>
          <h1 className="title">英単語暗記カード</h1>
          <p style={{ fontSize: '0.85rem', color: 'var(--text-light)', marginTop: '4px' }}>
            カードをクリックして裏返そう！
          </p>
        </div>
        <div className="stats">
          覚え済み: {rememberedCount} / {totalCount} 語 ({totalCount > 0 ? Math.round((rememberedCount / totalCount) * 100) : 0}%)
        </div>
      </header>

      <div className="controls">
        <button
          type="button"
          className={`btn ${viewMode === 'study' ? 'btn-primary' : ''}`}
          onClick={() => setViewMode('study')}
        >
          学習モード
        </button>
        <button
          type="button"
          className={`btn ${viewMode === 'list' ? 'btn-primary' : ''}`}
          onClick={() => setViewMode('list')}
        >
          単語一覧
        </button>
        <button
          type="button"
          className={`btn ${viewMode === 'add' ? 'btn-primary' : ''}`}
          onClick={() => setViewMode('add')}
        >
          単語追加
        </button>

        <div style={{ marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: '8px' }}>
          <span style={{ fontSize: '0.9rem', fontWeight: 600 }}>カテゴリ:</span>
          <select
            className="select"
            value={selectedCategory}
            onChange={(e) => setSelectedCategory(e.target.value)}
          >
            {categories.map((cat) => (
              <option key={cat} value={cat}>
                {cat}
              </option>
            ))}
          </select>
        </div>
      </div>

      <main>
        {viewMode === 'study' && (
          filteredCards.length === 0 ? (
            <div className="empty-msg">該当する単語がありません。</div>
          ) : (
            <div className="card-grid">
              {filteredCards.map((card) => (
                <Flashcard
                  key={card.id}
                  card={card}
                  onToggleRemembered={handleToggleRemembered}
                />
              ))}
            </div>
          )
        )}

        {viewMode === 'list' && (
          <WordList
            cards={filteredCards}
            onToggleRemembered={handleToggleRemembered}
            onDelete={handleDeleteCard}
          />
        )}

        {viewMode === 'add' && (
          <AddWord onAdd={handleAddCard} />
        )}
      </main>
    </div>
  );
}
